after.content:
        }
        return existing;
    }
    long nextSequence = acceptedSequence + 1;
    CanonicalFacts.AcceptedCommand command = new CanonicalFacts.AcceptedCommand(
            commandId, nextSequence, hash, resultRef);
    accepted.put(commandId, command);
    acceptedSequence = nextSequence;
    return command;
}
